WITH lines AS (SELECT id, customer_id, coupon_codes, INLINE(items) FROM carts) SELECT product_id, SUM(qty) AS total_qty, SIZE(COLLECT_SET(promo)) AS num_promos, SUM(CASE WHEN promo = 'SPRING10' THEN price ELSE 0 END) AS spring10_price, COUNT_IF(promo = 'WELCOME5') AS welcome5_events, COUNT(DISTINCT customer_id) AS distinct_customer_ids, AVG(product_id) AS avg_product_id FROM lines GROUP BY product_id;
